@app.cell(hide_code=True)
def _(comparison, mo, plt):
    _plot_rows = [r for r in comparison if r["Mean signed excess return"] is not None]
    mo.stop(not _plot_rows, mo.md("**Outcomes pending.** The initial 2026 release cannot yet answer the five-session return question."))
    _plot_rows.sort(key=lambda r: r["Mean signed excess return"])
    fig, ax = plt.subplots(figsize=(8, max(3, len(_plot_rows)*.36)), layout="constrained")
    for _i, _row in enumerate(_plot_rows):
        _agent = _row["Method"] in ["default-committee", "luna-committee", "single-luna"]
        ax.scatter(_row["Mean signed excess return"]*100, _i, color="#b76822" if _agent else "#34556e", marker="D" if _agent else "o", s=45)
    ax.set_yticks(range(len(_plot_rows)), [r["Method"] for r in _plot_rows])
    ax.axvline(0, color="#777777", linewidth=.8)
    ax.set_xlabel("Mean signed excess return vs SPY (percentage points)")
    ax.set_title("Direction × realized stock-minus-SPY return")
    ax.grid(axis="x", alpha=.15)
    mo.vstack([mo.as_html(fig), mo.md("Diamonds: LLM systems. Circles: numerical methods. Exact values and denominators are in the table. "
                                    "This descriptive mean is not a trading return or a significance test.")])
    return


